32	static int open_socket(void)
33	{
34	    struct addrinfo hints = {0}, *res, *p;
35	    hints.ai_socktype = SOCK_STREAM;
36	    hints.ai_family = AF_UNSPEC;
37	    int dns_rc = getaddrinfo(BROKER, PORT, &hints, &res);
38	    if (dns_rc != 0) {
39	        syslog(LOG_INFO, "[claude-mqtt] DNS failed for %s:%s rc=%d\n", BROKER, PORT, dns_rc);
40	        return -1;
41	    }
42	    int fd = -1;
43	    for (p = res; p; p = p->ai_next) {
44	        fd = socket(p->ai_family, p->ai_socktype, p->ai_protocol);
45	        if (fd >= 0 && connect(fd, p->ai_addr, p->ai_addrlen) == 0) {
46	            syslog(LOG_INFO, "[claude-mqtt] TCP connected to %s:%s\n", BROKER, PORT);
47	            break;
48	        }
49	        if (fd >= 0) { syslog(LOG_INFO, "[claude-mqtt] TCP connect failed errno=%d\n", errno); close(fd); fd = -1; }
50	    }
51	    freeaddrinfo(res);
52	    /* MQTT-C requires a non-blocking socket (mqtt_pal_recvall treats
53	     * EAGAIN/EWOULDBLOCK as "no data"). Without this, mqtt_sync blocks in
54	     * recv(), CONNECT never gets sent, and the broker drops the idle socket
55	     * after ~30s -> SOCKET_ERROR reconnect loop. */
56	    if (fd >= 0)
57	        fcntl(fd, F_SETFL, fcntl(fd, F_GETFL, 0) | O_NONBLOCK);
58	    return fd;
59	}
