61	static void publish_cb(void **unused, struct mqtt_response_publish *p)
62	{
63	    char state[16];
64	    (void)unused;
65	    if (p->topic_name_size != sizeof(TOPIC) - 1 ||
66	        memcmp(p->topic_name, TOPIC, sizeof(TOPIC) - 1) != 0 ||
67	        p->application_message_size >= sizeof(state)) {
68	        syslog(LOG_INFO, "[claude-mqtt] ignored publish topic_len=%u payload_len=%u\n",
69	               p->topic_name_size, (unsigned)p->application_message_size);
70	        return;
71	    }
72	    memcpy(state, p->application_message, p->application_message_size);
73	    state[p->application_message_size] = '\0';
74	    if (strcmp(state, "online") && strcmp(state, "offline") &&
75	        strcmp(state, "idle") && strcmp(state, "thinking") && strcmp(state, "executing")) {
76	        syslog(LOG_INFO, "[claude-mqtt] ignored state=%s\n", state);
77	        return;
78	    }
79	    syslog(LOG_INFO, "[claude-mqtt] received state=%s\n", state);
80	    pthread_mutex_lock(&g_lock);
81	    if (!strcmp(state, "online")) {
82	        strcpy(g_pending, "idle");
83	    } else if (!strcmp(state, "offline")) {
84	        strcpy(g_pending, "default");
85	    } else {
86	        strcpy(g_pending, state);
87	    }
88	    g_changed = true;
89	    pthread_mutex_unlock(&g_lock);
90	}
