92	static void *mqtt_worker(void *arg)
93	{
94	    struct mqtt_ctx *ctx = arg;
95	    struct mqtt_client client;
96	
97	    syslog(LOG_INFO, "[claude-mqtt] worker entered\n");
98	
99	    while (g_running) {
100	        /* 1. Establish TCP to the broker (waits for Wi-Fi/DNS to come up). */
101	        int fd = open_socket();
102	        if (fd < 0) {
103	            sleep(3);           /* backoff: avoid CPU/log flood before network is up */
104	            continue;
105	        }
106	
107	        /* 2. Fresh client each connection: init + CONNECT + SUBSCRIBE. */
108	        if (mqtt_init(&client, fd, ctx->sendbuf, sizeof(ctx->sendbuf),
109	                      ctx->recvbuf, sizeof(ctx->recvbuf), publish_cb) != MQTT_OK) {
110	            syslog(LOG_INFO, "[claude-mqtt] mqtt_init failed\n");
111	            close(fd);
112	            sleep(3);
113	            continue;
114	        }
115	        mqtt_connect(&client, "vela-home-scense", NULL, NULL, 0, NULL, NULL,
116	                     MQTT_CONNECT_CLEAN_SESSION, 60);
117	        if (client.error != MQTT_OK) {
118	            syslog(LOG_INFO, "[claude-mqtt] connect failed, retrying\n");
119	            close(fd);
120	            sleep(3);
121	            continue;
122	        }
123	        mqtt_subscribe(&client, TOPIC, 0);
124	        syslog(LOG_INFO, "[claude-mqtt] connected + subscribed, topic=%s\n", TOPIC);
125	
126	        /* 3. Pump traffic until an error, then reconnect. */
127	        while (g_running) {
128	            enum MQTTErrors err = mqtt_sync(&client);
129	            if (err != MQTT_OK) {
130	                syslog(LOG_INFO, "[claude-mqtt] sync error=%s, reconnecting\n",
131	                       mqtt_error_str(err));
132	                break;
133	            }
134	            usleep(100000);
135	        }
136	        close(fd);
137	        sleep(1);
138	    }
139	    return NULL;
140	}
