142	void claude_mqtt_init(void)
143	{
144	    static struct mqtt_ctx ctx;
145	    pthread_attr_t attr;
146	    int rc;
147	
148	    if (g_started) {
149	        syslog(LOG_INFO, "[claude-mqtt] init skipped: already started\n");
150	        return;
151	    }
152	    syslog(LOG_INFO, "[claude-mqtt] init begin\n");
153	    g_running = true;
154	    pthread_attr_init(&attr);
155	    rc = pthread_attr_setstacksize(&attr, 65536);
156	    if (rc != 0)
157	        syslog(LOG_INFO, "[claude-mqtt] pthread_attr_setstacksize failed rc=%d\n", rc);
158	    rc = pthread_create(&g_thread, &attr, mqtt_worker, &ctx);
159	    pthread_attr_destroy(&attr);
160	    if (rc != 0) {
161	        syslog(LOG_INFO, "[claude-mqtt] pthread_create failed rc=%d\n", rc);
162	        g_running = false;
163	        return;
164	    }
165	    g_started = true;
166	    syslog(LOG_INFO, "[claude-mqtt] worker created\n");
167	}
