169	void claude_mqtt_poll(lv_timer_t *timer)
170	{
171	    static uint32_t lease;
172	    char state[16];
173	    bool changed;
174	    (void)timer;
175	    pthread_mutex_lock(&g_lock);
176	    changed = g_changed;
177	    if (changed) { strcpy(state, g_pending); strcpy(g_state, g_pending); g_changed = false; lease = lv_tick_get(); }
178	    else strcpy(state, g_state);
179	    pthread_mutex_unlock(&g_lock);
180	    if (changed || !strcmp(state, "default") || lv_tick_elaps(lease) < LEASE_SECONDS * 1000) {
181	        ui_claude_status_set(state);
182	        if (!strcmp(state, "default")) { led_off(); }
183	        else if (!strcmp(state, "idle")) { led_set_mode_static(LED_COLOR_BLUE); led_on(); }
184	        else { led_set_mode_blink(LED_COLOR_GREEN, 2); led_on(); }
185	    } else {
186	        pthread_mutex_lock(&g_lock); strcpy(g_state, "default"); pthread_mutex_unlock(&g_lock);
187	        ui_claude_status_set("default"); led_off();
188	    }
189	}
